/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field MultiLineDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventTableModuleMultiLineDisc extends GUPPricingAttributeInventTableModule implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, MultiLineDisc);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    PriceDiscGroup   priceDiscGroup;

    while select GroupId from priceDiscGroup
        where priceDiscGroup.Type == PriceGroupType::MultiLineDiscGroup
           && priceDiscGroup.Module == ModuleInventCustVend::Invent
    {
        if (!ret.in(priceDiscGroup.GroupId))
        {
            ret.add(priceDiscGroup.GroupId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, MultiLineDisc));
    qbr.value(queryValue(_value));
}
